PREFIX s4bldg: <http://example.org/s4bldg/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?space
WHERE {
    ?space s4bldg:isSpaceOf ?building .
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?subsystem
WHERE {
    ?system ssn:hasSubSystem ?subsystem .
    FILTER NOT EXISTS { ?subsystem rdf:type rdf:Property }
}

PREFIX ssn-system: <http://www.w3.org/ns/ssn/system/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?condition
WHERE {
    ?system ssn-system:inCondition ?condition .
    FILTER EXISTS { ?system rdf:type ?type }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?property
WHERE {
    { :Neighbourhood rdf:type owl:Class .
      ?property rdfs:domain :Neighbourhood }
    UNION
    { :Neighbourhood rdf:type owl:Class .
      ?property rdfs:range :Neighbourhood }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?x
WHERE {
    ?x rdf:type :DigitalUser .
    FILTER NOT EXISTS { 
        ?x :hasNeighbourhood [] .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?neighbourhood
WHERE {
    ?neighbourhood rdf:type :Neighbourhood .
    FILTER NOT EXISTS { 
        ?agent rdf:type :Agent . 
        ?agent :hasNeighbourhood ?neighbourhood 
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?agent
WHERE {
    ?agent rdf:type :Agent .
    FILTER NOT EXISTS {
        ?agent rdf:type :DigitalUser .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?neighbourhood
WHERE {
    ?neighbourhood rdf:type :Neighbourhood .
    FILTER NOT EXISTS {
        ?agent rdf:type :Agent .
        ?agent :isInvolvedIn ?neighbourhood .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?x
WHERE {
    rdf:value rdfs:isDefinedBy ?x .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
    ?property rdf:type owl:ObjectProperty .
    {
        { ?property rdfs:subPropertyOf rdf:value . }
        UNION
        { 
            ?property rdfs:domain rdfs:Resource .
            ?property rdfs:range rdfs:Resource .
        }
    }
    FILTER (?property = :hasMinValue || ?property = :hasMaxValue) .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?value ?format
WHERE {
    ?value rdf:type :Value .
    OPTIONAL { 
        ?value :expressedInFormat ?format . 
    }
    BIND(EXISTS { ?value :literalValue ?any } AS ?hasLiteral)
    FILTER(?hasLiteral || EXISTS { ?value :hasMinValue ?any } || EXISTS { ?value :hasMaxValue ?any })
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?x
WHERE {
    ?x rdf:type :ThingDescription .
}

PREFIX saref4city: <https://w3id.org/def/saref4city#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?adminArea
WHERE {
    ?adminArea rdf:type saref4city:AdministrativeArea .
    ?city1 rdf:type saref4city:City ;
          rdf:type ?adminArea .
    ?city2 rdf:type saref4city:City ;
          rdf:type ?adminArea .
    FILTER (?city1 != ?city2)
}

PREFIX saref: <https://w3id.org/saref#>
PREFIX s4city: <https://w3id.org/def/saref4city#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?service
WHERE {
    ?city rdf:type s4city:City .
    ?service rdf:type saref:Service .
    FILTER NOT EXISTS { ?city saref:offers ?service . }
}

PREFIX ssn-system: <http://www.ssn-system.org/>
PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?systemLifetime ?survivalRange
WHERE {
    ?device a ssn-system:SystemProperty .
    ?device rdfs:subClassOf ssn-system:OperatingProperty .
    OPTIONAL { ?device ssn-system:SystemLifetime ?systemLifetime . }
    OPTIONAL { ?device ssn:SurvivalRange ?survivalRange . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX ssn-system: <http://www.sensorml.com/ont/swe/property/>
PREFIX : <http://example.org/>

SELECT ?thingEcosystemDescription ?purpose
WHERE {
    ?thingEcosystemDescription rdf:type :ThingEcosystemDescription .
    OPTIONAL { ?thingEcosystemDescription rdfs:comment ?purpose . }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?feature ?geometry
WHERE {
    ?feature rdf:type geo:Feature .
    ?geometry rdf:type geo:Geometry .
    FILTER EXISTS {
        { ?feature geo:sfContains ?geometry } 
        UNION 
        { ?feature geo:sfWithin ?geometry }
        UNION 
        { ?geometry geo:sfContains ?feature }
        UNION 
        { ?geometry geo:sfWithin ?feature }
    }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?building ?space ?feature 
WHERE {
    ?building rdf:type s4bldg:Building .
    ?space rdf:type s4bldg:BuildingSpace .
    ?feature rdf:type geo:Feature .
    FILTER NOT EXISTS { ?building geo:sfWithin ?space }
    {
        ?building geo:sfContains ?space .
        OPTIONAL { 
            ?space geo:sfWithin ?feature .
        }
        OPTIONAL { 
            ?space geo:sfContains ?feature .
        }
    }
}

PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?building
WHERE {
    ?building rdf:type s4bldg:Building .
    FILTER NOT EXISTS { 
        ?building prov:hadPrimarySource ?primarySource .
        FILTER (?primarySource != <http://www.buildingsmart-tech.org/ifc/IFC4/Add1/html/schema/ifcproductextension/lexical/ifcbuilding.htm>)
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>
PREFIX prov: <http://www.w3.org/ns/prov#>

SELECT ?building ?feature ?geometry ?relation
WHERE {
    ?building rdf:type s4bldg:BuildingSpace .
    ?building rdfs:subClassOf ?mid .
    ?mid rdfs:subClassOf* geo:Feature .
    ?feature rdf:type geo:Feature .
    ?geometry rdf:type geo:Geometry .
    {
        { ?building geo:sfContains ?feature . BIND("sfContains" AS ?relation) }
        UNION
        { ?feature geo:sfWithin ?building . BIND("sfWithin" AS ?relation) }
    }
    FILTER NOT EXISTS { 
        ?feature owl:disjointWith ?geometry .
    }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>

SELECT ?relationship
WHERE {
    {
        ?building a s4bldg:Building .
        ?otherFeature a geo:Feature .
        { 
            ?building geo:sfContains ?otherFeature . 
            BIND(geo:sfContains AS ?relationship) 
        }
        UNION
        { 
            ?otherFeature geo:sfContains ?building . 
            BIND(geo:sfContains AS ?relationship) 
        }
        UNION
        { 
            ?building geo:sfWithin ?otherFeature . 
            BIND(geo:sfWithin AS ?relationship) 
        }
        UNION
        { 
            ?otherFeature geo:sfWithin ?building . 
            BIND(geo:sfWithin AS ?relationship) 
        }
    }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?buildingSpace
WHERE {
    ?buildingSpace rdf:type s4bldg:BuildingSpace .
    OPTIONAL { 
        ?buildingSpace geo:sfWithin ?location . 
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>
PREFIX prov: <http://www.w3.org/ns/prov#>

SELECT ?building ?definition
WHERE {
    ?building rdf:type s4bldg:Building .
    ?building rdfs:subClassOf geo:Feature .
    ?building prov:hadPrimarySource <http://www.buildingsmart-tech.org/ifc/IFC4/Add1/html/schema/ifcproductextension/lexical/ifcbuilding.htm> .
    ?building rdfs:seeAlso ?ifcBuilding .
    ?ifcBuilding rdf:type owl:Class .
    ?definition rdf:type geo:SpatialObject .
    {
        ?building geo:sfContains ?definition .
    } UNION {
        ?definition geo:sfWithin ?building .
    }
    FILTER NOT EXISTS { ?building rdfs:seeAlso ?otherIfcBuilding . FILTER (?otherIfcBuilding != ?ifcBuilding) }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?publisher 
WHERE {
    <http://iot.linkeddata.es/def/core#> dc:publisher ?publisher .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT DISTINCT ?entity ?role
WHERE {
    {
        <http://iot.linkeddata.es/def/core#> dcterms:creator ?creator .
        BIND("Creator" AS ?role)
        BIND(?creator AS ?entity) 
    }
    UNION
    {
        <http://iot.linkeddata.es/def/core#> dcterms:contributor ?contributor .
        BIND("Contributor" AS ?role)
        BIND(?contributor AS ?entity) 
    }
    UNION
    {
        <http://iot.linkeddata.es/def/core#> dc:publisher ?publisher .
        BIND("Publisher" AS ?role)
        BIND(?publisher AS ?entity) 
    }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?purpose
WHERE {
    <http://iot.linkeddata.es/def/core#> owl:imports sosa: .
    OPTIONAL { <http://iot.linkeddata.es/def/core#> dcterms:description ?purpose . }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?url
WHERE {
    <http://iot.linkeddata.es/def/core#> dcterms:creator|dcterms:contributor|dc:publisher ?url .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?contribution 
WHERE {
    <http://iot.linkeddata.es/def/core#> dcterms:contributor <http://www.oeg-upm.net/index.php/en/universitystaff/402-fserena/> .
    <http://iot.linkeddata.es/def/core#> rdf:type owl:Ontology .
    OPTIONAL { <http://www.oeg-upm.net/index.php/en/universitystaff/402-fserena/> ?p ?contribution . FILTER (?p != dcterms:contributor && ?p != rdf:type) }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?term
WHERE {
    <http://iot.linkeddata.es/def/core#> dcterms:license <http://purl.org/NET/rdflicense/cc-by4.0> .
    OPTIONAL { 
        { <http://purl.org/NET/rdflicense/cc-by4.0> rdf:type ?term . }
        UNION
        { <http://purl.org/NET/rdflicense/cc-by4.0> rdfs:label ?term . }
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?annotationProperty
WHERE {
    ?annotationProperty rdf:type owl:AnnotationProperty .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX vs: <http://www.w3.org/2003/06/sw-vocab-status/ns#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?resource ?primaryContributor
WHERE {
    ?resource dcterms:contributor ?contributor .
    OPTIONAL { 
        ?resource dc:creator ?primaryContributor . 
        FILTER NOT EXISTS { 
            ?resource dcterms:contributor ?otherContributor . 
            FILTER (?otherContributor != ?primaryContributor) 
        } 
    }
    {
        SELECT ?resource (COUNT(DISTINCT ?contributor) AS ?count)
        WHERE {
            ?resource dcterms:contributor ?contributor .
        }
        GROUP BY ?resource
        HAVING (?count > 1)
    }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX vs: <http://www.w3.org/2003/06/sw-vocab-status/ns#>

SELECT ?resource ?source
WHERE {
    ?resource dc:source ?source .
    FILTER EXISTS {
        SELECT ?resource (COUNT(DISTINCT ?s) AS ?sourceCount)
        WHERE {
            ?resource dc:source ?s .
        }
        GROUP BY ?resource
        HAVING (?sourceCount > 1)
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?property
WHERE {
    { ?property rdf:type owl:AnnotationProperty ; rdfs:label "creator"@en }
    UNION
    { ?property rdf:type owl:AnnotationProperty ; rdfs:label "contributor"@en }
    UNION
    { ?property rdf:type owl:AnnotationProperty ; rdfs:label ?label .
      FILTER (regex(str(?label), "creator", "i") || regex(str(?label), "contributor", "i")) 
    }
}

PREFIX vicinity: <https://vicinity.eu/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?attribute
WHERE {
    ?property rdfs:domain vicinity:Service ;
              rdfs:label ?attribute .
}

PREFIX org: <http://example.org/organization/>
PREFIX dev: <http://example.dev/device/>
PREFIX serv: <http://example.serv/service/>
PREFIX integ: <http://example.integ/integration/>

SELECT ?organization ?device ?service
WHERE {
    ?organization a org:Organization .
    ?organization org:hasDevice ?device .
    ?organization org:hasService ?service .
    ?device dev:isIntegratedWith ?service .
    ?service serv:isProvidedBy ?organization .
    OPTIONAL {
        ?integration integ:integrates ?device, ?service .
        ?integration integ:partOf ?organization .
    }
    FILTER NOT EXISTS { 
        ?device dev:isIntegratedWith ?wrongService .
        FILTER (?wrongService != ?service) .
    }
}

PREFIX vic: <http://vicinity.eu/ontology#>
SELECT ?purpose
WHERE {
    ?partnership rdf:type vic:Partnership .
    ?partnership vic:purpose ?purpose .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX event: <http://example.com/event/>
PREFIX obs: <http://example.com/observation/>

SELECT DISTINCT ?property
WHERE {
    ?scale rdf:type event:WeightScale .
    ?event rdf:type event:Event ;
           event:involves ?scale .
    ?observation rdf:type obs:Observation ;
                 obs:ofEvent ?event ;
                 obs:observes ?property .
}

PREFIX org: <http://www.example.org/>
PREFIX unikl: <http://www.unikl.org/>

SELECT (COUNT(DISTINCT ?organization) AS ?count)
WHERE {
    ?organization org:hasPartnership unikl:UNIKL .
}
